package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
class DiscussionApiTest {
 StudyApiTest f;DiscussionStore store;DiscussionController api;UUID study;
 @BeforeEach void setup(){f=new StudyApiTest();f.setup();study=new UuidV7(Clock.systemUTC()).next();store=mock(DiscussionStore.class);api=new DiscussionController(store,f.api,new SimpleMeterRegistry());}
 MockHttpServletRequest req(String method,String body){var r=f.req(method,body);r.removeHeader("If-Match");r.addHeader("If-Match","\"di1\"");return r;}
 DiscussionStore.Discussion value(){return new DiscussionStore.Discussion(f.id,study,f.group,f.space,f.actor,1,"Topic","Body","OPEN","GROUP_MEMBERS",Instant.now().toString(),Instant.now().toString());}
 @Test void memberCreatesAndRepliesButCannotModerateEvenOwnDiscussion()throws Exception{
  f.role("MEMBER");when(store.create(eq(f.group),eq(f.space),eq(study),eq(f.actor),anyString(),eq("Study"),eq("Purpose"),anyString())).thenReturn(new DiscussionStore.Result(value(),true));var v=api.create(f.group.toString(),study.toString(),req("POST",f.settings()));assertEquals(201,v.getStatusCode().value());assertEquals("\"di1\"",v.getHeaders().getETag());assertEquals("no-store",v.getHeaders().getCacheControl());assertTrue(v.getHeaders().getLocation().toString().endsWith("/discussions/"+f.id));
  var reply=new DiscussionStore.Reply(f.id,f.id,study,f.group,f.space,f.actor,1,1,"Reply","GROUP_MEMBERS",Instant.now().toString());when(store.reply(eq(f.group),eq(f.space),eq(study),eq(f.id),eq(f.actor),eq(1L),anyString(),eq("Reply"),anyString())).thenReturn(new DiscussionStore.ReplyResult(reply,true),new DiscussionStore.ReplyResult(reply,false));assertEquals(201,api.reply(f.group.toString(),study.toString(),f.id.toString(),req("POST","{\"content\":\"Reply\"}")).getStatusCode().value());assertEquals(200,api.reply(f.group.toString(),study.toString(),f.id.toString(),req("POST","{\"content\":\"Reply\"}")).getStatusCode().value());assertThrows(ResponseStatusException.class,()->api.state(f.group.toString(),study.toString(),f.id.toString(),req("PUT","{\"state\":\"LOCKED\"}")));assertThrows(ResponseStatusException.class,()->api.retire(f.group.toString(),study.toString(),f.id.toString(),req("DELETE",null)));
 }
 @Test void viewerReadsButCannotCreateOrReplyAndCatalogReflectsArchivedParent()throws Exception{
  f.role("VIEWER");when(store.list(f.group,f.space,study,null,20)).thenReturn(new DiscussionStore.Page(List.of(),null,false));var response=api.list(f.group.toString(),study.toString(),req("GET",null));assertFalse(((DiscussionController.Catalog)response.getBody()).canWrite());assertEquals(403,assertThrows(ResponseStatusException.class,()->api.create(f.group.toString(),study.toString(),req("POST",f.settings()))).getStatusCode().value());assertThrows(ResponseStatusException.class,()->api.reply(f.group.toString(),study.toString(),f.id.toString(),req("POST","{\"content\":\"Reply\"}")));f.role("MEMBER");when(store.list(f.group,f.space,study,null,20)).thenReturn(new DiscussionStore.Page(List.of(),null,true));assertFalse(((DiscussionController.Catalog)api.list(f.group.toString(),study.toString(),req("GET",null)).getBody()).canWrite());
 }
 @Test void secureOriginAndFreshMembershipRejectionNeverReachStore(){var insecure=req("POST",f.settings());insecure.setSecure(false);var duplicate=req("POST",f.settings());duplicate.addHeader("Cookie","__Host-brain_guest="+f.token);var origin=req("POST",f.settings());origin.addHeader("Origin","https://elsewhere.example");for(var v:List.of(insecure,duplicate,origin))assertThrows(ResponseStatusException.class,()->api.create(f.group.toString(),study.toString(),v));verifyNoInteractions(f.auth,store);when(f.auth.participation(any(),anyList(),anyString())).thenReturn(new GroupSpaceClient.Access(f.actor,"REGISTERED",List.of()));assertThrows(ResponseStatusException.class,()->api.list(f.group.toString(),study.toString(),req("GET",null)));verifyNoInteractions(store);}
 @Test void strictBodiesReplyUnicodeKeysAndEtagsRejectAmbiguity(){
  for(String text:List.of("{}","{\"content\":\"\"}","{\"content\":\"A\",\"content\":\"B\"}","{\"content\":\"A\",\"authorId\":\"spoof\"}","{\"content\":\"A\"} {}","{\"content\":\"\\ud800\"}","{\"content\":\"\\u0000\"}"))assertThrows(ResponseStatusException.class,()->api.reply(f.group.toString(),study.toString(),f.id.toString(),req("POST",text)));
  var missing=req("POST","{\"content\":\"Reply\"}");missing.removeHeader("If-Match");assertEquals(428,assertThrows(ResponseStatusException.class,()->api.reply(f.group.toString(),study.toString(),f.id.toString(),missing)).getStatusCode().value());for(String tag:List.of("*","W/\"di1\"","\"su1\"","\"di0\"","\"di9999999999999999999\"")){var v=req("DELETE",null);v.removeHeader("If-Match");v.addHeader("If-Match",tag);assertThrows(ResponseStatusException.class,()->api.retire(f.group.toString(),study.toString(),f.id.toString(),v));}var key=req("POST",f.settings());key.addHeader("Idempotency-Key","b".repeat(32));assertThrows(ResponseStatusException.class,()->api.create(f.group.toString(),study.toString(),key));verifyNoInteractions(store);
 }
 @Test void readBodiesQueriesAndByteBoundsStayStrict(){var read=req("GET","{}");assertThrows(ResponseStatusException.class,()->api.list(f.group.toString(),study.toString(),read));var q=req("GET",null);q.addParameter("authorId",f.actor.toString());assertThrows(ResponseStatusException.class,()->api.list(f.group.toString(),study.toString(),q));var page=req("GET",null);page.addParameter("limit","11");assertThrows(ResponseStatusException.class,()->api.replies(f.group.toString(),study.toString(),f.id.toString(),page));var large=req("POST","x".repeat(65537));assertEquals(413,assertThrows(ResponseStatusException.class,()->api.create(f.group.toString(),study.toString(),large)).getStatusCode().value());assertThrows(ResponseStatusException.class,()->DiscussionStore.content(("{\"content\":\""+"한".repeat(10923)+"\"}").getBytes(java.nio.charset.StandardCharsets.UTF_8)));verifyNoInteractions(store);}
}
